// Iterative function to find an object by its 'name' property deep inside a given object, returning the path to it
function findObjectByName(obj, targetName) {
  const stack = [{ current: obj, path: [] }];
  const visited = new Set();
  while (stack.length > 0) {
    const { current, path } = stack.pop();
    if (current && typeof current === 'object' && !visited.has(current)) {
      visited.add(current);
      if (current.name === targetName) {
        return path;
      }
      for (const key of Object.keys(current)) {
        if (typeof current[key] === 'object' && current[key] !== null) {
          stack.push({ current: current[key], path: path.concat(key) });
        }
      }
    }
  }
  return null; // Not found
}
