import os
import zipfile
import sys
from pathlib import Path

def archive_files_in_folder(folder_path):
    """Archive each non-hidden file in the specified folder into a separate zip file."""
    folder = Path(folder_path)
    if not folder.is_dir():
        print(f"Error: {folder_path} is not a valid directory.")
        return
    files = [f for f in folder.iterdir() if f.is_file() and not f.name.startswith('.') and not f.suffix == '.zip']
    if not files:
        print("No files to archive in the specified folder.")
        return
    for file in files:
        zip_filename = folder / f"{file.stem}.zip"
        if zip_filename.exists():
            print(f"Warning: {zip_filename.name} already exists. Skipping {file.name}.")
            continue
        try:
            with zipfile.ZipFile(zip_filename, 'w', zipfile.ZIP_DEFLATED) as zipf:
                zipf.write(file, arcname=file.name)
            print(f"Archived {file.name} to {zip_filename.name}")
        except PermissionError:
            print(f"Permission denied: Cannot archive {file.name}")
        except Exception as e:
            print(f"Error archiving {file.name}: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python archive_folder.py <folder_path>")
        sys.exit(1)
    folder_path = sys.argv[1]
    archive_files_in_folder(folder_path)

if __name__ == "__main__":
    main()

To create a new parameter P2(A,C) in GAMS such that each value of P2 takes the mapped value from P1(A,B), where there is a one-to-one mapping from B to C, you can proceed as follows:

set A /a1*a3/;
set B /b1*b3/;
set C /c1*c3/;

* Define the mapping from B to C:
set map(B,C) /b1.c2, b2.c3, b3.c1/;

* Define parameter P1(A,B):
parameter P1(A,B);
P1('a1','b1') = 10;
P1('a1','b2') = 20;
P1('a1','b3') = 30;
* ... (other values as needed)

* Now, define P2(A,C) using the mapping:
parameter P2(A,C);
P2(a,c) = sum((b), P1(a,b)*map(b,c));

* This assigns to P2(a,c) the value of P1(a,b) where b maps to c.

Explanation: The sum over b with map(b,c) ensures that only the mapped pair contributes (since map(b,c) is 1 only for the mapped pair, 0 otherwise). This is a standard GAMS idiom for applying a mapping between sets when reindexing parameters.

