void handleCmdLineArgs(const char *args) {
    int length = 0;
    // Calculate the length of the input string
    while (args[length] != '\0') {
        length++;
    }
    int i = 0;
    while (i < length) {
        // Check if the current character is part of a valid SJIS sequence
        if (RK_CheckSJIS((unsigned char)args[i])) {
            i++;
        } else if (args[i] == '/') {
            char nextChar = args[i + 1];
            if (nextChar == 'w' || nextChar == 'W') {
                IsWindowedMode = 1;
