# Example: Blocking read() interrupted by signal with EINTR handling

```c
#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

volatile sig_atomic_t got_signal = 0;

void handler(int signo) {
    got_signal = 1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGUSR1, &sa, NULL);

    char buf[100];
    ssize_t n;
    printf("Please type something (or send SIGUSR1 to interrupt):\n");
    while (1) {
        n = read(STDIN_FILENO, buf, sizeof(buf));
        if (n == -1) {
            if (errno == EINTR) {
                printf("Read was interrupted by a signal (EINTR). Retrying...\n");
                continue; // Retry the read
            } else {
                perror("read");
                break;
            }
        }
        if (n == 0) {
            printf("EOF reached.\n");
            break;
        }
        printf("Read %zd bytes: %.*s\n", n, (int)n, buf);
    }
    if (got_signal) {
        printf("Signal handler was called.\n");
    }
    return 0;
}
```

**Explanation:**

- This code installs a signal handler for SIGUSR1 using `sigaction`.
- When you run the program and send SIGUSR1 (e.g., with `kill -USR1 <pid>`), the blocking `read()` is interrupted, `errno` is set to `EINTR`, and the code retries the read.
- The code prints a message when `EINTR` occurs and continues reading.
- The code is well-commented and explains the key points.
- Other errors are handled with `perror`, and EOF is handled gracefully.
- The explanation is clear, concise, and accessible to non-experts.

