public void MergeWordDocuments(string firstDocPath, string secondDocPath, string outputDocPath)
{
    using (WordprocessingDocument firstDoc = WordprocessingDocument.Open(firstDocPath, false))
    using (WordprocessingDocument secondDoc = WordprocessingDocument.Open(secondDocPath, false))
    using (WordprocessingDocument outputDoc = WordprocessingDocument.Create(outputDocPath, WordprocessingDocumentType.Document))
    {
        // Clone the main part from the first document
        outputDoc.AddMainDocumentPart();
        outputDoc.MainDocumentPart.Document = (Document)firstDoc.MainDocumentPart.Document.CloneNode(true);

        // Copy styles, fonts, header, footer from the first document
        if (firstDoc.MainDocumentPart.StyleDefinitionsPart != null)
        {
            outputDoc.MainDocumentPart.AddNewPart<StyleDefinitionsPart>();
            outputDoc.MainDocumentPart.StyleDefinitionsPart.FeedData(firstDoc.MainDocumentPart.StyleDefinitionsPart.GetStream());
        }
        if (firstDoc.MainDocumentPart.FontTablePart != null)
        {
            outputDoc.MainDocumentPart.AddNewPart<FontTablePart>();
            outputDoc.MainDocumentPart.FontTablePart.FeedData(firstDoc.MainDocumentPart.FontTablePart.GetStream());
        }
        // Copy headers and footers
        foreach (var header in firstDoc.MainDocumentPart.HeaderParts)
        {
            var newHeader = outputDoc.MainDocumentPart.AddNewPart<HeaderPart>();
            newHeader.FeedData(header.GetStream());
        }
        foreach (var footer in firstDoc.MainDocumentPart.FooterParts)
        {
            var newFooter = outputDoc.MainDocumentPart.AddNewPart<FooterPart>();
            newFooter.FeedData(footer.GetStream());
        }

        // Keep only the first 2 pages from the first document
        var body = outputDoc.MainDocumentPart.Document.Body;
        var paragraphs = body.Elements<Paragraph>().ToList();
        int pageCount = 0, paraIndex = 0;
        for (; paraIndex < paragraphs.Count && pageCount < 2; paraIndex++)
        {
            if (paragraphs[paraIndex].Descendants<Break>().Any(b => b.Type == BreakValues.Page))
                pageCount++;
        }
        // Remove content after the second page
        while (paraIndex < paragraphs.Count)
        {
            paragraphs[paraIndex].Remove();
            paraIndex++;
        }

        // Append main content and glossary from the second document
        var secondBody = secondDoc.MainDocumentPart.Document.Body;
        // Assume glossary is the last section with heading 'Glossary'
        bool inGlossary = false;
        foreach (var elem in secondBody.Elements())
        {
            if (elem is Paragraph p && p.InnerText.Trim().Equals("Glossary", StringComparison.OrdinalIgnoreCase))
                inGlossary = true;
            if (!inGlossary || (inGlossary && p.InnerText.Trim().Length > 0))
                body.Append(elem.CloneNode(true));
        }

        // Copy images from both documents
        foreach (var imagePart in firstDoc.MainDocumentPart.ImageParts)
        {
            var newImagePart = outputDoc.MainDocumentPart.AddImagePart(imagePart.ContentType);
            newImagePart.FeedData(imagePart.GetStream());
        }
        foreach (var imagePart in secondDoc.MainDocumentPart.ImageParts)
        {
            var newImagePart = outputDoc.MainDocumentPart.AddImagePart(imagePart.ContentType);
            newImagePart.FeedData(imagePart.GetStream());
        }

        outputDoc.MainDocumentPart.Document.Save();
    }
}

