# Elo rating calculator for a chess tournament

class Player:
    def __init__(self, name, rating=1200):
        self.name = name
        self.rating = rating

class EloTournament:
    def __init__(self, k_factor=32):
        self.players = {}
        self.k = k_factor

    def get_player(self, name):
        if name not in self.players:
            self.players[name] = Player(name)
        return self.players[name]

    def expected_score(self, rating_a, rating_b):
        return 1 / (1 + 10 ** ((rating_b - rating_a) / 400))

    def update_ratings(self, player_a, player_b, result):
        # result: 1 = A wins, 0.5 = draw, 0 = B wins
        expected_a = self.expected_score(player_a.rating, player_b.rating)
        expected_b = self.expected_score(player_b.rating, player_a.rating)
        player_a.rating += self.k * (result - expected_a)
        player_b.rating += self.k * ((1 - result) - expected_b)

    def process_game(self, name_a, name_b, result):
        player_a = self.get_player(name_a)
        player_b = self.get_player(name_b)
        if result not in [0, 0.5, 1]:
            raise ValueError('Invalid result: must be 0, 0.5, or 1')
        self.update_ratings(player_a, player_b, result)

    def process_tournament(self, games):
        for game in games:
            self.process_game(*game)

    def get_ratings(self):
        return {name: round(player.rating, 2) for name, player in self.players.items()}

