function fibonacciMod(n, p) {
    if (typeof n !== 'number' || typeof p !== 'number' || n < 0 || p <= 0) {
        throw new Error('Invalid input: n must be a non-negative integer and p must be a positive integer.');
    }
    if (n === 0) return 0 % p;
    if (n === 1) return 1 % p;
    let a = 0, b = 1;
    for (let i = 2; i <= n; i++) {
        let temp = (a + b) % p;
        a = b;
        b = temp;
    }
    return b;
}
