import csv
import os
import re
from collections import namedtuple, defaultdict

def load_records(filename):
    records = []
    with open(filename, newline='', encoding='utf-8') as csvfile:
        reader = csv.reader(csvfile)
        for row in reader:
            if len(row) == 12:
                records.append(tuple(row))
    return records

def normalize_field(field):
    # Remove non-alphanumeric for phone, date, etc.
    return re.sub(r'\W+', '', field).lower()

def score_text_file(text, records):
    text_norm = normalize_field(text)
    scores = defaultdict(int)
    for idx, record in enumerate(records):
        match_count = 0
        for field in record:
            if field and normalize_field(field) in text_norm:
                match_count += 1
        if match_count > 0:
            scores[idx] = match_count
    return scores

def main(records_file, text_files, threshold):
    records = load_records(records_file)
    for text_file in text_files:
        try:
            with open(text_file, encoding='utf-8') as f:
                text = f.read()
        except Exception as e:
            print(f"Error reading {text_file}: {e}")
            continue
        scores = score_text_file(text, records)
        for idx, score in scores.items():
            if score >= threshold:
                print(f"{text_file} matches record {idx} with score {score}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) < 4:
        print("Usage: python program.py records.csv file1.txt file2.txt ... threshold")
    else:
        records_file = sys.argv[1]
        text_files = sys.argv[2:-1]
        threshold = int(sys.argv[-1])
        main(records_file, text_files, threshold)

