% Kalman Sequence Filter implementation in GNU Octave
function [x_est, P_est] = kalman_filter(z, A, H, Q, R, x0, P0)
% KALMAN_FILTER Implements the Kalman sequence filter for linear systems.
%   [x_est, P_est] = kalman_filter(z, A, H, Q, R, x0, P0)
%   z  - Observations (measurements), matrix of size (num_obs x num_steps)
%   A  - State transition matrix
%   H  - Observation matrix
%   Q  - Process noise covariance matrix
%   R  - Measurement noise covariance matrix
%   x0 - Initial state estimate
%   P0 - Initial covariance estimate
%   x_est - Estimated states (num_states x num_steps)
%   P_est - Estimated covariances (num_states x num_states x num_steps)

num_steps = size(z, 2);
num_states = size(A, 1);
x_est = zeros(num_states, num_steps);
P_est = zeros(num_states, num_states, num_steps);

x_prev = x0;
P_prev = P0;

for k = 1:num_steps
    % Prediction step
    x_pred = A * x_prev;
    P_pred = A * P_prev * A' + Q;

    % Update step
    K = P_pred * H' / (H * P_pred * H' + R); % Kalman gain
    x_curr = x_pred + K * (z(:,k) - H * x_pred);
    P_curr = (eye(num_states) - K * H) * P_pred;

    % Store results
    x_est(:,k) = x_curr;
    P_est(:,:,k) = P_curr;

    % Prepare for next iteration
    x_prev = x_curr;
    P_prev = P_curr;
end
end

% Example usage:
% A = [1 1; 0 1]; H = [1 0]; Q = 0.01*eye(2); R = 1; x0 = [0; 1]; P0 = eye(2);
% z = [measurement data];
% [x_est, P_est] = kalman_filter(z, A, H, Q, R, x0, P0);

