class MainActivity : AppCompatActivity() {
    private lateinit var audioRecord: AudioRecord
    private lateinit var audioTrack: AudioTrack
    private val bufferSize = AudioRecord.getMinBufferSize(44100, AudioFormat.CHANNEL_IN_MONO, AudioFormat.ENCODING_PCM_16BIT)
    private val nativeLib = System.loadLibrary("native-lib")

    external fun processReverb(buffer: ShortArray): ShortArray

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        // Request RECORD_AUDIO permission
        if (ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO) != PackageManager.PERMISSION_GRANTED) {
            ActivityCompat.requestPermissions(this, arrayOf(Manifest.permission.RECORD_AUDIO), 1)
        }
        audioRecord = AudioRecord(MediaRecorder.AudioSource.MIC, 44100, AudioFormat.CHANNEL_IN_MONO, AudioFormat.ENCODING_PCM_16BIT, bufferSize)
        audioTrack = AudioTrack(AudioManager.STREAM_MUSIC, 44100, AudioFormat.CHANNEL_OUT_MONO, AudioFormat.ENCODING_PCM_16BIT, bufferSize, AudioTrack.MODE_STREAM)
        Thread {
            val buffer = ShortArray(bufferSize)
            audioRecord.startRecording()
            audioTrack.play()
            while (true) {
                val read = audioRecord.read(buffer, 0, buffer.size)
                if (read > 0) {
                    val processed = processReverb(buffer)
                    audioTrack.write(processed, 0, processed.size)
                }
            }
        }.start()
    }
    override fun onDestroy() {
        super.onDestroy()
        audioRecord.stop()
        audioRecord.release()
        audioTrack.stop()
        audioTrack.release()
    }
}

// native-lib.cpp (C++)
#include <jni.h>
#include <vector>

extern "C" JNIEXPORT jshortArray JNICALL
Java_com_example_app_MainActivity_processReverb(JNIEnv* env, jobject, jshortArray inputArray) {
    jsize len = env->GetArrayLength(inputArray);
    jshort* input = env->GetShortArrayElements(inputArray, nullptr);
    std::vector<jshort> output(len);
    const int delay = 4410; // 100ms at 44.1kHz
    const float feedback = 0.6f;
    std::vector<float> delayBuffer(delay, 0);
    for (int i = 0; i < len; ++i) {
        float dry = input[i];
        float wet = delayBuffer[i % delay];
        float out = dry + feedback * wet;
        if (out > 32767) out = 32767;
        if (out < -32768) out = -32768;
        output[i] = static_cast<jshort>(out);
        delayBuffer[i % delay] = out;
    }
    env->ReleaseShortArrayElements(inputArray, input, 0);
    jshortArray result = env->NewShortArray(len);
    env->SetShortArrayRegion(result, 0, len, output.data());
    return result;
}
