import android.app.Service
import android.content.Intent
import android.net.VpnService
import android.os.ParcelFileDescriptor
import java.io.FileInputStream
import java.io.FileOutputStream
import java.net.InetAddress
import java.nio.ByteBuffer
import java.util.concurrent.Executors

class LocalVpnService : VpnService() {
    private var vpnInterface: ParcelFileDescriptor? = null
    private val executor = Executors.newSingleThreadExecutor()

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        val builder = Builder()
        builder.setSession("MyVPNService")
            .addAddress("10.0.0.2", 32)
            .addRoute("0.0.0.0", 0)
        vpnInterface = builder.establish()
        executor.execute { runVpn() }
        return Service.START_STICKY
    }

    private fun runVpn() {
        val input = FileInputStream(vpnInterface?.fileDescriptor)
        val output = FileOutputStream(vpnInterface?.fileDescriptor)
        val packet = ByteArray(32767)
        while (true) {
            val length = input.read(packet)
            if (length > 0) {
                val destIp = extractDestinationIp(packet)
                if (destIp != null && shouldAllow(destIp)) {
                    output.write(packet, 0, length)
                } // else: drop packet
            }
        }
    }

    private fun extractDestinationIp(packet: ByteArray): String? {
        if (packet.size < 20) return null // Not a valid IP packet
        val buffer = ByteBuffer.wrap(packet)
        val version = (buffer.get(0).toInt() shr 4) and 0xF
        if (version == 4) {
            val destIpBytes = ByteArray(4)
            buffer.position(16)
            buffer.get(destIpBytes, 0, 4)
            return InetAddress.getByAddress(destIpBytes).hostAddress
        }
        return null // Only IPv4 supported in this example
    }

    private fun shouldAllow(destIp: String): Boolean {
        // Example: block 8.8.8.8, allow others
        return destIp != "8.8.8.8"
    }

    override fun onDestroy() {
        vpnInterface?.close()
        executor.shutdownNow()
        super.onDestroy()
    }
}

