import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Files;
import java.nio.file.Paths;

public class KubeLogClient {
    private final String apiServerUrl;
    private final String token;

    public KubeLogClient(String apiServerUrl, String token) {
        this.apiServerUrl = apiServerUrl;
        this.token = token;
    }

    public String getPodLogs(String namespace, String podName) throws Exception {
        String url = String.format("%s/api/v1/namespaces/%s/pods/%s/log", apiServerUrl, namespace, podName);
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(url))
            .header("Authorization", "Bearer " + token)
            .GET()
            .build();
        HttpClient client = HttpClient.newBuilder()
            .build();
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        if (response.statusCode() == 200) {
            return response.body();
        } else {
            throw new RuntimeException("Failed to get logs: " + response.statusCode() + " " + response.body());
        }
    }

    public static void main(String[] args) throws Exception {
        // Example usage:
        String apiServer = "https://kubernetes.default.svc"; // or from kubeconfig
        String token = Files.readString(Paths.get("/var/run/secrets/kubernetes.io/serviceaccount/token"));
        KubeLogClient client = new KubeLogClient(apiServer, token);
        String logs = client.getPodLogs("default", "my-pod");
        System.out.println(logs);
    }
}
