// FavoritesManager.php
namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    public function add($name)
    {
        if (Auth::check()) {
            $user = Auth::user();
            Favorite::firstOrCreate([
                'user_id' => $user->id,
                'name' => $name,
            ]);
        } else {
            $favorites = Session::get('favorites', []);
            if (!in_array($name, $favorites)) {
                $favorites[] = $name;
                Session::put('favorites', $favorites);
            }
        }
    }

    public function remove($name)
    {
        if (Auth::check()) {
            $user = Auth::user();
            Favorite::where('user_id', $user->id)->where('name', $name)->delete();
        } else {
            $favorites = Session::get('favorites', []);
            $favorites = array_filter($favorites, fn($n) => $n !== $name);
            Session::put('favorites', $favorites);
        }
    }

    public function list()
    {
        if (Auth::check()) {
            $user = Auth::user();
            return Favorite::where('user_id', $user->id)->pluck('name')->toArray();
        } else {
            return Session::get('favorites', []);
        }
    }
}

