def solve_quadratic(a, b, c):
    """
    Solves the quadratic equation ax^2 + bx + c = 0.
    Returns a tuple of roots. Handles real and complex roots.
    If a == 0, handles as a linear equation or returns None if invalid.
    """
    import cmath
    if a == 0:
        if b == 0:
            return None  # Not an equation
        else:
            return (-c / b, )  # Linear equation
    discriminant = b**2 - 4*a*c
    sqrt_disc = cmath.sqrt(discriminant)
    root1 = (-b + sqrt_disc) / (2*a)
    root2 = (-b - sqrt_disc) / (2*a)
    if root1 == root2:
        return (root1, )
    return (root1, root2)

