    function mintCreds(address to, uint256 amount) public onlyOwner {
        require(to != address(0), "Cannot mint to zero address");
        _mint(to, CREDS, amount, "");
        hasCreds[to] = true;
    }

    // Override safeTransferFrom to update hasCreds mapping
    function safeTransferFrom(
        address from,
        address to,
        uint256 id,
        uint256 amount,
        bytes memory data
    ) public override {
        super.safeTransferFrom(from, to, id, amount, data);
        if (id == CREDS && balanceOf(to, CREDS) > 0) {
            hasCreds[to] = true;
        }
        if (id == CREDS && balanceOf(from, CREDS) == 0) {
            hasCreds[from] = false;
        }
    }

    // Optional: function to check if an address has creds
    function checkCreds(address user) public view returns (bool) {
