// TypeScript implementation of TCP parsing from an IPv4 payload (Uint8Array)
interface TCPHeader {
  sourcePort: number;
  destPort: number;
  sequenceNumber: number;
  acknowledgmentNumber: number;
  dataOffset: number;
  reserved: number;
  flags: {
    ns: boolean;
    cwr: boolean;
    ece: boolean;
    urg: boolean;
    ack: boolean;
    psh: boolean;
    rst: boolean;
    syn: boolean;
    fin: boolean;
  };
  windowSize: number;
  checksum: number;
  urgentPointer: number;
  options?: Uint8Array;
  data: Uint8Array;
}

function parseTCPPacket(payload: Uint8Array): TCPHeader | null {
  if (payload.length < 20) return null; // Minimum TCP header size
  const view = new DataView(payload.buffer, payload.byteOffset, payload.byteLength);
  const sourcePort = view.getUint16(0);
  const destPort = view.getUint16(2);
  const sequenceNumber = view.getUint32(4);
  const acknowledgmentNumber = view.getUint32(8);
  const dataOffset = (payload[12] >> 4) & 0xf;
  const reserved = (payload[12] & 0x0e) >> 1;
  const ns = (payload[12] & 0x01) !== 0;
  const flagsByte = payload[13];
  const flags = {
    cwr: (flagsByte & 0x80) !== 0,
    ece: (flagsByte & 0x40) !== 0,
    urg: (flagsByte & 0x20) !== 0,
    ack: (flagsByte & 0x10) !== 0,
    psh: (flagsByte & 0x08) !== 0,
    rst: (flagsByte & 0x04) !== 0,
    syn: (flagsByte & 0x02) !== 0,
    fin: (flagsByte & 0x01) !== 0,
    ns,
  };
  const windowSize = view.getUint16(14);
  const checksum = view.getUint16(16);
  const urgentPointer = view.getUint16(18);
  const headerLength = dataOffset * 4;
  if (payload.length < headerLength) return null; // Malformed packet
  let options: Uint8Array | undefined = undefined;
  if (headerLength > 20) {
    options = payload.slice(20, headerLength);
  }
  const data = payload.slice(headerLength);
  return {
    sourcePort,
    destPort,
    sequenceNumber,
    acknowledgmentNumber,
    dataOffset,
    reserved,
    flags,
    windowSize,
    checksum,
    urgentPointer,
    options,
    data,
  };
}

