    texture2d<float, access::read>  inTexture  [[texture(0)]],
    texture2d<float, access::write> outTexture [[texture(1)]],
    uint2 gid [[thread_position_in_grid]]) {
    if (gid.x >= inTexture.get_width() || gid.y >= inTexture.get_height()) {
        return;
    }
    float4 color = float4(0.0);
    int kernelRadius = 2; // 5x5 kernel
    for (int y = -kernelRadius; y <= kernelRadius; ++y) {
        for (int x = -kernelRadius; x <= kernelRadius; ++x) {
            int2 coord = int2(gid) + int2(x, y);
            // Clamp coordinates to image bounds
            coord.x = clamp(coord.x, 0, int(inTexture.get_width()) - 1);
            coord.y = clamp(coord.y, 0, int(inTexture.get_height()) - 1);
            float4 sample = inTexture.read(uint2(coord));
            color += sample * gaussianKernel[y + kernelRadius][x + kernelRadius];
        }
    }
    outTexture.write(color, gid);
}
// This kernel applies a 5x5 Gaussian blur to an input image, handling edge pixels by clamping coordinates. The kernel is general for any image size. Comments explain key steps.

