// Strategy Pattern Example: Banking App System

// Step 1: Define strategy interface (as functions in JS)
class TransactionStrategy {
  execute(amount, account) {
    throw new Error('execute() must be implemented');
  }
}

// Step 2: Implement concrete strategies
class DepositStrategy extends TransactionStrategy {
  execute(amount, account) {
    account.balance += amount;
    console.log(`Deposited $${amount}. New balance: $${account.balance}`);
  }
}

class WithdrawStrategy extends TransactionStrategy {
  execute(amount, account) {
    if (account.balance >= amount) {
      account.balance -= amount;
      console.log(`Withdrew $${amount}. New balance: $${account.balance}`);
    } else {
      console.log('Insufficient funds!');
    }
  }
}

class CashbackStrategy extends TransactionStrategy {
  execute(amount, account) {
    const cashback = amount * 0.05;
    account.balance += cashback;
    console.log(`Cashback of $${cashback} applied! New balance: $${account.balance}`);
  }
}

// Step 3: Context class
class BankAccount {
  constructor(owner, balance = 0) {
    this.owner = owner;
    this.balance = balance;
    this.transactionStrategy = null;
  }

  setTransactionStrategy(strategy) {
    this.transactionStrategy = strategy;
  }

  performTransaction(amount) {
    if (!this.transactionStrategy) {
      console.log('No transaction strategy set!');
      return;
    }
    this.transactionStrategy.execute(amount, this);
  }
}

// Step 4: Usage example
const account = new BankAccount('Alice', 100);

account.setTransactionStrategy(new DepositStrategy());
account.performTransaction(50); // Deposited $50. New balance: $150

account.setTransactionStrategy(new WithdrawStrategy());
account.performTransaction(70); // Withdrew $70. New balance: $80

account.setTransactionStrategy(new CashbackStrategy());
account.performTransaction(200); // Cashback of $10 applied! New balance: $90

