# PERN Stack To-Do List App

## 1. PostgreSQL Database Setup

Create a database named `perntodo` and a `todos` table:
```sql
CREATE TABLE todos (
  id SERIAL PRIMARY KEY,
  description TEXT NOT NULL,
  completed BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
```

## 2. Backend (Node.js + Express.js)

**Install dependencies:**
```
npm install express pg cors dotenv
```

**server.js:**
```js
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const { Pool } = require('pg');

const app = express();
app.use(cors());
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Create a to-do
app.post('/todos', async (req, res) => {
  try {
    const { description } = req.body;
    const newTodo = await pool.query(
      'INSERT INTO todos (description) VALUES ($1) RETURNING *',
      [description]
    );
    res.json(newTodo.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Get all to-dos
app.get('/todos', async (req, res) => {
  try {
    const todos = await pool.query('SELECT * FROM todos ORDER BY created_at DESC');
    res.json(todos.rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Update a to-do
app.put('/todos/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const { description, completed } = req.body;
    const updateTodo = await pool.query(
      'UPDATE todos SET description = $1, completed = $2 WHERE id = $3 RETURNING *',
      [description, completed, id]
    );
    res.json(updateTodo.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Delete a to-do
app.delete('/todos/:id', async (req, res) => {
  try {
    const { id } = req.params;
    await pool.query('DELETE FROM todos WHERE id = $1', [id]);
    res.json({ message: 'To-do deleted' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

## 3. Frontend (React)

**Install dependencies:**
```
npx create-react-app client
cd client
npm install axios
```

**src/App.js:**
```jsx
import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [todos, setTodos] = useState([]);
  const [description, setDescription] = useState('');

  useEffect(() => {
    fetchTodos();
  }, []);

  const fetchTodos = async () => {
    const res = await axios.get('http://localhost:5000/todos');
    setTodos(res.data);
  };

  const addTodo = async () => {
    if (!description) return;
    await axios.post('http://localhost:5000/todos', { description });
    setDescription('');
    fetchTodos();
  };

  const toggleComplete = async (id, completed, desc) => {
    await axios.put(`http://localhost:5000/todos/${id}`, { description: desc, completed: !completed });
    fetchTodos();
  };

  const deleteTodo = async (id) => {
    await axios.delete(`http://localhost:5000/todos/${id}`);
    fetchTodos();
  };

  return (
    <div style={{ maxWidth: 400, margin: 'auto' }}>
      <h2>To-Do List</h2>
      <input
        value={description}
        onChange={e => setDescription(e.target.value)}
        placeholder="Add a new to-do"
      />
      <button onClick={addTodo}>Add</button>
      <ul>
        {todos.map(todo => (
          <li key={todo.id}>
            <span
              style={{ textDecoration: todo.completed ? 'line-through' : 'none', cursor: 'pointer' }}
              onClick={() => toggleComplete(todo.id, todo.completed, todo.description)}
            >
              {todo.description}
            </span>
            <button onClick={() => deleteTodo(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```

## 4. Setup Instructions

1. **Install PostgreSQL** and create a database named `perntodo`.
2. Run the provided SQL to create the `todos` table.
3. In the backend folder, run `npm install` and create a `.env` file with `DATABASE_URL=your_connection_string`.
4. Start the backend: `node server.js` (default port 5000).
5. In the `client` folder, run `npm install` and `npm start` (default port 3000).
6. Ensure backend and frontend are running on different ports.
7. If you encounter CORS issues, ensure `cors` is enabled in Express.

