// Example Vitis HLS C++ code for a simple MNIST neural network (1 hidden layer)
#include "ap_fixed.h"
#include "hls_stream.h"

#define INPUT_SIZE 784 // 28x28 pixels
#define HIDDEN_SIZE 64
#define OUTPUT_SIZE 10

typedef ap_fixed<16,6> data_t;

void mnist_nn(data_t input[INPUT_SIZE], data_t output[OUTPUT_SIZE],
              data_t w1[HIDDEN_SIZE][INPUT_SIZE], data_t b1[HIDDEN_SIZE],
              data_t w2[OUTPUT_SIZE][HIDDEN_SIZE], data_t b2[OUTPUT_SIZE]) {
#pragma HLS INTERFACE s_axilite port=return bundle=CTRL
#pragma HLS INTERFACE m_axi depth=784 port=input offset=slave
#pragma HLS INTERFACE m_axi depth=10 port=output offset=slave
#pragma HLS INTERFACE m_axi depth=64*784 port=w1 offset=slave
#pragma HLS INTERFACE m_axi depth=64 port=b1 offset=slave
#pragma HLS INTERFACE m_axi depth=10*64 port=w2 offset=slave
#pragma HLS INTERFACE m_axi depth=10 port=b2 offset=slave

    data_t hidden[HIDDEN_SIZE];
#pragma HLS ARRAY_PARTITION variable=hidden complete dim=1

    // Hidden layer
    for (int i = 0; i < HIDDEN_SIZE; i++) {
#pragma HLS UNROLL
        data_t sum = b1[i];
        for (int j = 0; j < INPUT_SIZE; j++) {
            sum += w1[i][j] * input[j];
        }
        // ReLU activation
        hidden[i] = (sum > 0) ? sum : 0;
    }

    // Output layer
    for (int i = 0; i < OUTPUT_SIZE; i++) {
#pragma HLS UNROLL
        data_t sum = b2[i];
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            sum += w2[i][j] * hidden[j];
        }
        output[i] = sum; // Softmax can be applied outside for inference
    }
}
