To efficiently find all prime numbers up to a given number n in MATLAB, I implemented the Sieve of Eratosthenes:

% Efficient Prime Search using Sieve of Eratosthenes
function primes_list = efficient_prime_search(n)
    if n < 2
        primes_list = [];
        return;
    end
    sieve = true(1, n);
    sieve(1) = false; % 1 is not prime
    for i = 2:sqrt(n)
        if sieve(i)
            sieve(2*i:i:n) = false;
        end
    end
    primes_list = find(sieve);
end

This function returns all primes up to n. For example, efficient_prime_search(20) returns [2 3 5 7 11 13 17 19]. The algorithm is efficient (O(n log log n)), uses logical indexing for speed, and is well-commented. For very large n, a segmented sieve or other optimizations could be considered.

use std::iter::Iterator;

struct PrimeStream {
    current: u64,
}

impl PrimeStream {
    fn new() -> Self {
        PrimeStream { current: 2 }
    }
}

fn is_prime(n: u64) -> bool {
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let sqrt_n = (n as f64).sqrt() as u64;
    for i in (3..=sqrt_n).step_by(2) {
        if n % i == 0 {
            return false;
        }
    }
    true
}

impl Iterator for PrimeStream {
    type Item = u64;
    fn next(&mut self) -> Option<Self::Item> {
        let mut n = self.current;
        loop {
            if is_prime(n) {
                self.current = n + 1;
                return Some(n);
            }
            n += 1;
        }
    }
}

fn main() {
    let primes = PrimeStream::new();
    for p in primes.take(10) {
        println!("{}", p);
    }
}
