// Simple RNN implementation in plain TypeScript

class SimpleRNN {
  inputSize: number;
  hiddenSize: number;
  outputSize: number;
  Wh: number[][]; // Input to hidden weights
  Uh: number[][]; // Hidden to hidden weights
  Wy: number[][]; // Hidden to output weights
  bh: number[];   // Hidden bias
  by: number[];   // Output bias
  h: number[];    // Hidden state

  constructor(inputSize: number, hiddenSize: number, outputSize: number) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize;
    this.Wh = this.randomMatrix(hiddenSize, inputSize);
    this.Uh = this.randomMatrix(hiddenSize, hiddenSize);
    this.Wy = this.randomMatrix(outputSize, hiddenSize);
    this.bh = new Array(hiddenSize).fill(0);
    this.by = new Array(outputSize).fill(0);
    this.h = new Array(hiddenSize).fill(0);
  }

  // Helper to create a matrix with small random values
  randomMatrix(rows: number, cols: number): number[][] {
    return Array.from({ length: rows }, () =>
      Array.from({ length: cols }, () => Math.random() * 0.2 - 0.1)
    );
  }

  // Simple tanh activation
  tanh(x: number[]): number[] {
    return x.map(v => Math.tanh(v));
  }

  // Matrix-vector multiplication
  matVecMul(mat: number[][], vec: number[]): number[] {
    return mat.map(row => row.reduce((sum, val, i) => sum + val * vec[i], 0));
  }

  // Vector addition
  vecAdd(a: number[], b: number[]): number[] {
    return a.map((v, i) => v + b[i]);
  }

  // Forward pass for a sequence of inputs
  forward(inputs: number[][]): number[][] {
    let outputs: number[][] = [];
    this.h = new Array(this.hiddenSize).fill(0); // Reset hidden state
    for (const x of inputs) {
      // h_t = tanh(Wh * x_t + Uh * h_{t-1} + bh)
      const Whx = this.matVecMul(this.Wh, x);
      const Uhh = this.matVecMul(this.Uh, this.h);
      const hRaw = this.vecAdd(this.vecAdd(Whx, Uhh), this.bh);
      this.h = this.tanh(hRaw);
      // y_t = Wy * h_t + by
      const y = this.vecAdd(this.matVecMul(this.Wy, this.h), this.by);
      outputs.push(y);
    }
    return outputs;
  }
}

