class Action:
    def __init__(self, config):
        """
        Initialize an Action from a config dict.
        Config example:
        {
            "name": "Life Leech",
            "target_effects": [
                {"type": "damage", "amount": "actor.damage"}
            ],
            "actor_effects": [
                {"type": "heal", "amount": "actor.damage * 0.5"}
            ]
        }
        """
        self.name = config["name"]
        self.actor_effects = config.get("actor_effects", [])
        self.target_effects = config.get("target_effects", [])

    def execute(self, actor, target=None):
        # Apply effects to actor
        for effect in self.actor_effects:
            self.apply_effect(effect, actor, actor, target)
        # Apply effects to target
        if target:
            for effect in self.target_effects:
                self.apply_effect(effect, target, actor, target)

    def apply_effect(self, effect, char, actor, target):
        amount = self.evaluate_formula(effect["amount"], actor, target)
        if effect["type"] == "heal":
            char.hp = min(char.hp + amount, getattr(char, 'max_hp', char.hp + amount))  # Prevent overheal if max_hp exists
        elif effect["type"] == "damage":
            char.hp = max(char.hp - amount, 0)  # Prevent negative HP
        # Extendable: add more effect types here

    def evaluate_formula(self, formula, actor, target):
        # Simple DSL: formula can be '10', 'actor.hp * 0.2', 'target.hp * 0.5', etc.
        # For safety, only allow certain names and operators
        allowed_names = {"actor": actor, "target": target}
        return int(eval(formula, {"__builtins__": None}, allowed_names))

