1. Set up your Pinia store (e.g., 'sessionStore') to hold the relevant session data:

// stores/session.js
import { defineStore } from 'pinia';
export const useSessionStore = defineStore('session', {
  state: () => ({
    userId: null,
    token: null,
    // add other keys as needed
  }),
  actions: {
    updateSession(data) {
      this.userId = data.userId;
      this.token = data.token;
    },
  },
});

2. Use @tanstack/vue-query's useQuery in your component to fetch data and select specific keys:

// In your component
import { useQuery } from '@tanstack/vue-query';
import { useSessionStore } from '@/stores/session';
import { onMounted, watch } from 'vue';

const sessionStore = useSessionStore();

const { data, isLoading, error } = useQuery([
  'session',
], async () => {
  const res = await fetch('/get_session');
  if (!res.ok) throw new Error('Network response was not ok');
  return res.json();
}, {
  select: (data) => ({
    userId: data.userId,
    token: data.token,
  }),
});

// Watch for changes and update the store
watch(data, (newData) => {
  if (newData) {
    sessionStore.updateSession(newData);
  }
}, { immediate: true });

// Now, the Pinia store will be updated with the selected keys from the response whenever the query succeeds.

