% Water Wave Simulation in a Tank Driven by Wind (Matlab Live Script)
% Tank dimensions
L = 0.42; % length in meters
W = 0.36; % width in meters
wind_speed = 2.5; % m/s

% Discretization
Nx = 100; Ny = 80;
x = linspace(0, L, Nx);
y = linspace(0, W, Ny);
[X, Y] = meshgrid(x, y);

% Physical parameters
rho = 1000; % water density (kg/m^3)
g = 9.81; % gravity (m/s^2)
H = 0.05; % assumed water depth (m)

% Wave parameters (simplified linear wave theory)
A = 0.005; % initial amplitude (m)
T = 2; % period (s)
omega = 2*pi/T;
k = omega^2/g; % deep water approx

% Wind forcing (simplified, constant over surface)
wind_force = 0.5 * 1.2 * wind_speed^2; % N/m^2, air density = 1.2 kg/m^3

% Time parameters
Tmax = 10; dt = 0.05;
t = 0:dt:Tmax;

% Initialize surface elevation
eta = zeros(Ny, Nx, length(t));

% Main loop: simulate wave growth due to wind (simplified)
for ti = 2:length(t)
    % Simple growth model: amplitude increases with wind force
    growth = wind_force * dt * 1e-4; % arbitrary scaling for demo
    eta(:,:,ti) = A * sin(k*X) .* sin(k*Y) * exp(growth*ti) + eta(:,:,ti-1)*0.98;
end

% Visualization
for ti = 1:10:length(t)
    surf(X, Y, eta(:,:,ti));
    zlim([-0.02 0.02]);
    xlabel('x (m)'); ylabel('y (m)'); zlabel('Surface Elevation (m)');
    title(['Water Surface at t = ', num2str(t(ti)), ' s']);
    drawnow;
end

% Assumptions and Limitations:
% - Linear wave theory, no nonlinear effects
% - Wind force applied uniformly, no turbulence
% - No wave breaking or tank wall effects
% - Water depth assumed constant and shallow
% - Model is for demonstration, not for precise engineering analysis

function findEntityKey(json, entityKey, currentPath = []) {
  let results = [];
  if (typeof json === 'object' && json !== null) {
    if (Array.isArray(json)) {
      json.forEach((item, idx) => {
        results = results.concat(findEntityKey(item, entityKey, currentPath.concat([idx])));
      });
    } else {
      Object.keys(json).forEach(key => {
        if (key === entityKey) {
          results.push({
            value: json[key],
            location: currentPath.concat([key])
          });
        }
        results = results.concat(findEntityKey(json[key], entityKey, currentPath.concat([key])));
      });
    }
  }
  return results;
}

// Example usage:
// const data = { a: 1, b: { a: 2, c: [{ a: 3 }, { d: 4 }] } };
// findEntityKey(data, 'a')
// Output: [ { value: 1, location: ['a'] }, { value: 2, location: ['b','a'] }, { value: 3, location: ['b','c',0,'a'] } ]

