use strict;
use warnings;
use File::Basename;
use Cwd 'abs_path';

# Get script directory and source video.sh (Perl can't source bash, so note this)
my $DIR = dirname(abs_path($0));
# NOTE: Perl cannot source bash scripts directly. If video.sh defines functions, they must be ported or called via system.

# Initialize variables
my ($quality, $preset, $resize, $noise, $input_file) = ("", "", "", "", "");

# Parse command-line arguments
while (@ARGV) {
    my $arg = shift @ARGV;
    if ($arg eq '-q' || $arg eq '--quality') {
        $quality = shift @ARGV;
    } elsif ($arg eq '-p' || $arg eq '--preset') {
        $preset = shift @ARGV;
    } elsif ($arg eq '-r' || $arg eq '--resize') {
        $resize = shift @ARGV;
    } elsif ($arg eq '-n' || $arg eq '--noise') {
        $noise = shift @ARGV;
    } else {
        $input_file = $arg;
    }
}

# Check if input file exists
if (!-f $input_file) {
    print STDERR "FILE NOT FOUND: $input_file\n";
}

# Check for required arguments
if ($quality eq '' || $preset eq '' || $input_file eq '') {
    print STDERR "Usage: $0 -q|--quality <quality> -p|--preset <preset> [-n|--noise <noise_level>] [-r|--resize <size>] <input_file>\n";
    exit 1;
}

my $file_path = abs_path($input_file);
# get-filename is a bash function; in Perl, use basename without extension
my $file_name = basename($file_path);
$file_name =~ s/\.[^.]+$//; # Remove extension

my $chunk_method = "ffms2";

my $output_name = "$file_name.reencode.av1an.aom.rf$quality.p$preset";
my $metadata_comment = "reencoded with av1an(aom), 10-bit, cpu-used=$preset, cq=$quality, chunk-method=$chunk_method";

if ($noise ne '') {
    $output_name .= ".noise$noise";
} else {
    $noise = 10;
}

if ($resize ne '') {
    $output_name .= ".$resize" . 'p';
}

# Set ulimit (not directly possible in Perl, but can be done via system)
system('ulimit -n 2048');

my $threads = 2;

# Build ffmpeg filter string
my $ffmpeg_filter = ($resize ne '') ? " -vf 'scale=-1:$resize'" : '';

# Run av1an
my $av1an_cmd = join(' ',
    'av1an --verbose',
    "-i '$file_path'",
    '--encoder aom',
    '--workers 4',
    '--resume',
    '--extra-split 300',
    '--ignore-frame-mismatch',
    '--audio-params " -an "',
    "--ffmpeg \" -an$ffmpeg_filter\"",
    '--split-method av-scenechange --chunk-method', $chunk_method, '--concat mkvmerge',
    "--set-thread-affinity=$threads",
    "--photon-noise=$noise",
    '--video-params " '
        . '--bit-depth=10 '
        . "--threads=$threads "
        . '--end-usage=q --cq-level=' . $quality . ' --cpu-used=' . $preset . ' '
        . '--tile-columns=0 --tile-rows=0 '
        . '--tune-content=psy --tune=ssim '
        . '--lag-in-frames=64 '
        . '--enable-keyframe-filtering=1 --disable-kf --kf-max-dist=9999 '
        . '--enable-qm=1 --deltaq-mode=0 --aq-mode=0 --quant-b-adapt=1 '
        . '--enable-fwd-kf=0 --arnr-strength=4 --sb-size=dynamic --enable-dnl-denoising=0 '
    . '"',
    "-o '$output_name.audioless.mkv'"
);
system($av1an_cmd) == 0 or die "Failed to run av1an: $?";

# Put the audio back and convert to mp4
my $ffmpeg_cmd = "ffmpeg -loglevel warning -hide_banner -i '$output_name.audioless.mkv' -i '$file_path' -c copy -map 0:v -map 1:a -metadata comment=\"$metadata_comment\" '$output_name.mp4'";
system($ffmpeg_cmd) == 0 or die "Failed to run ffmpeg: $?";

# Remove intermediate file
unlink "$output_name.audioless.mkv";

# List files (exa may not be available, so fallback to ls)
if (system('which exa > /dev/null 2>&1') == 0) {
    system("exa -al --color=always --no-permissions --no-user --time-style=long-iso '$input_file' '$output_name.mp4'");
} else {
    system("ls -l '$input_file' '$output_name.mp4'");
}

print "\nvideo-compare '$input_file' '$output_name.mp4'\n";
print "\n✅ FINISHED\n";

In Swift, pattern matching with conditionals is commonly done using 'switch' statements with 'where' clauses, as well as 'if case' and 'guard case' statements. Here are some examples:

1. Using 'switch' with 'where':

let number = 15
switch number {
case let x where x % 2 == 0:
    print("Even number: \(x)")
case let x where x % 2 != 0:
    print("Odd number: \(x)")
default:
    break
}

2. Using 'if case' with a condition:

let value: Optional<Int> = 10
if case let .some(x) = value, x > 5 {
    print("Value is greater than 5: \(x)")
}

3. Using 'guard case' with a condition:

func process(value: Int?) {
    guard case let .some(x) = value, x > 0 else {
        print("Value is nil or not positive")
        return
    }
    print("Positive value: \(x)")
}

These approaches allow you to match patterns and add extra conditions to control the flow of your Swift programs.

function retryRequest(requestFn, retries = 3) {
  return new Promise((resolve, reject) => {
    function attempt(remaining) {
      requestFn()
        .then(resolve)
        .catch((err) => {
          if (remaining > 1) {
            attempt(remaining - 1);
          } else {
            reject(err);
          }
        });
    }
    attempt(retries);
  });
}

