- Two players take turns dropping their pieces (X and O) into columns 1-7.
- The first player to get four in a row (horizontally, vertically, or diagonally) wins.
- If the board fills up with no winner, it's a tie.
"""

def display_board(board):
    print("\n 1 2 3 4 5 6 7")
    for row in board:
        print('|' + '|'.join(row) + '|')
    print("-----------------")

def make_move(board, col, player):
    for row in reversed(board):
        if row[col] == ' ':
            row[col] = player
            return True
    return False

def check_win(board, player):
    # Check horizontal
    for row in board:
        for c in range(4):
            if all(row[c+i] == player for i in range(4)):
                return True
    # Check vertical
    for c in range(7):
        for r in range(3):
            if all(board[r+i][c] == player for i in range(4)):
                return True
    # Check diagonal (down-right)
    for r in range(3):
        for c in range(4):
            if all(board[r+i][c+i] == player for i in range(4)):
                return True
    # Check diagonal (up-right)
    for r in range(3,6):
        for c in range(4):
            if all(board[r-i][c+i] == player for i in range(4)):
                return True
    return False

def is_full(board):
    return all(cell != ' ' for row in board for cell in row)

def main():
    board = [[' ' for _ in range(7)] for _ in range(6)]
    players = ['X', 'O']
    turn = 0
    print("Welcome to Connect-4!")
    while True:
        display_board(board)
        player = players[turn % 2]
        while True:
            try:
                move = input(f"Player {turn%2+1} ({player}), enter column (1-7): ")
                col = int(move) - 1
                if col < 0 or col > 6:
                    print("Invalid column. Please enter a number from 1 to 7.")
                    continue
                if not make_move(board, col, player):
                    print("Column is full, try again.")
                    continue
                break
            except ValueError:
                print("Invalid input, please enter a number from 1 to 7.")
            except (EOFError, KeyboardInterrupt):
                print("\nGame exited.")
                return
        if check_win(board, player):
            display_board(board)
            print(f"Player {turn%2+1} ({player}) wins! Congratulations!")
            break
        if is_full(board):
            display_board(board)
            print("It's a tie!")
            break
        turn += 1

if __name__ == "__main__":
    main()

