use std::fs::File;
use std::io::{self, BufRead};
use std::path::Path;
use std::process::Command;

fn main() {
    let path = "urls.txt";
    let file = match File::open(&path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Failed to open file {}: {}", path, e);
            return;
        }
    };

    let reader = io::BufReader::new(file);
    let mut youtube_urls = Vec::new();
    let mut other_urls = Vec::new();

    for line in reader.lines() {
        match line {
            Ok(url) => {
                if url.contains("youtube.com/watch?v=") || url.contains("youtu.be/") {
                    youtube_urls.push(url);
                } else {
                    other_urls.push(url);
                }
            }
            Err(e) => {
                eprintln!("Error reading line: {}", e);
            }
        }
    }

    println!("Found {} YouTube URLs:", youtube_urls.len());
    for url in &youtube_urls {
        println!("  {}", url);
    }
    println!("Found {} other URLs:", other_urls.len());
    for url in &other_urls {
        println!("  {}", url);
    }

    for url in &youtube_urls {
        println!("Downloading: {}", url);
        let status = Command::new("yt-dlp")
            .arg(url)
            .status();
        match status {
            Ok(s) if s.success() => println!("Downloaded successfully."),
            Ok(s) => eprintln!("yt-dlp failed with exit code: {}", s),
            Err(e) => eprintln!("Failed to run yt-dlp: {}", e),
        }
    }
}

